// Standardized ThreatLocker organization names
const standardizedNames = [
  // Organization names exactly as they appear in ThreatLocker
  "Contoso Ltd",
  "Fabrikam Inc",
  "Northwind Traders"
];

// --- Hard mappings (bypasses fuzzy matching) ---
const hardMappings = {
  "contoso": "Contoso Ltd",
  // Add more hard mappings here as needed:
  // "some other name": "Matched Name",
};

// Function to calculate string similarity (Jaro-Winkler-like)
function calculateSimilarity(str1, str2) {
  const s1 = str1.toLowerCase().replace(/[^a-z0-9]/g, '');
  const s2 = str2.toLowerCase().replace(/[^a-z0-9]/g, '');

  if (s1 === s2) return 1.0;
  if (s1.length === 0 || s2.length === 0) return 0.0;

  if (s1.includes(s2) || s2.includes(s1)) {
    return 0.8 + (0.2 * Math.min(s1.length, s2.length) / Math.max(s1.length, s2.length));
  }

  const matrix = Array(s2.length + 1).fill().map(() => Array(s1.length + 1).fill(0));

  for (let i = 0; i <= s1.length; i++) matrix[0][i] = i;
  for (let j = 0; j <= s2.length; j++) matrix[j][0] = j;

  for (let j = 1; j <= s2.length; j++) {
    for (let i = 1; i <= s1.length; i++) {
      const cost = s1[i - 1] === s2[j - 1] ? 0 : 1;
      matrix[j][i] = Math.min(
        matrix[j - 1][i] + 1,
        matrix[j][i - 1] + 1,
        matrix[j - 1][i - 1] + cost
      );
    }
  }

  const maxLength = Math.max(s1.length, s2.length);
  return 1 - (matrix[s2.length][s1.length] / maxLength);
}

// Get the client name from input
const inputName = $input.first().json["Client Name"] || '';

// Handle empty input
if (!inputName) {
  return [{
    json: {
      originalInput: inputName,
      matchedName: null,
      similarity: 0,
      status: 'NO_INPUT',
      error: 'Client Name field is empty or missing'
    }
  }];
}

// --- Check hard mappings first (case-insensitive) ---
const hardMatch = hardMappings[inputName.toLowerCase().trim()];
if (hardMatch) {
  return [{
    json: {
      originalInput: inputName,
      matchedName: hardMatch,
      similarity: 1,
      status: 'HARD_MAPPED',
      threshold: null,
      allCandidates: []
    }
  }];
}

// Find best fuzzy match
let bestMatch = null;
let bestSimilarity = 0;

standardizedNames.forEach(standardName => {
  const similarity = calculateSimilarity(inputName, standardName);
  if (similarity > bestSimilarity) {
    bestSimilarity = similarity;
    bestMatch = standardName;
  }
});

const SIMILARITY_THRESHOLD = 0.75;

return [{
  json: {
    originalInput: inputName,
    matchedName: bestSimilarity >= SIMILARITY_THRESHOLD ? bestMatch : null,
    similarity: Math.round(bestSimilarity * 100) / 100,
    status: bestSimilarity >= SIMILARITY_THRESHOLD ? 'MATCHED' : 'NO_MATCH',
    threshold: SIMILARITY_THRESHOLD,
    allCandidates: standardizedNames.map(name => ({
      name: name,
      similarity: Math.round(calculateSimilarity(inputName, name) * 100) / 100
    })).sort((a, b) => b.similarity - a.similarity).slice(0, 3)
  }
}];

// Get all computer data from previous node
const computers = $input.all();

// Initialize counters
const stats = {
  totalEndpoints: 0,
  activeEndpoints: 0,
  offlineEndpoints: 0,
  inactiveEndpoints: 0,
  inactiveDevices: []
};

// Process each computer
computers.forEach(computer => {
  const data = computer.json;

  // Count total endpoints
  stats.totalEndpoints++;

  // Count by status
  const status = data.driverStatusString;
  switch(status) {
    case 'Active':
      stats.activeEndpoints++;
      break;
    case 'Offline':
      stats.offlineEndpoints++;
      break;
    case 'Inactive':
      stats.inactiveEndpoints++;
      // Add inactive device details
      stats.inactiveDevices.push({
        computerName: data.computerName,
        hostname: data.hostname,
        lastCheckin: data.lastCheckin
      });
      break;
  }
});

// Create final output
const result = {
  summary: {
    totalEndpoints: stats.totalEndpoints,
    activeEndpoints: stats.activeEndpoints,
    offlineEndpoints: stats.offlineEndpoints,
    inactiveEndpoints: stats.inactiveEndpoints,
    statusPercentages: {
      active: Math.round((stats.activeEndpoints / stats.totalEndpoints) * 100),
      offline: Math.round((stats.offlineEndpoints / stats.totalEndpoints) * 100),
      inactive: Math.round((stats.inactiveEndpoints / stats.totalEndpoints) * 100)
    }
  },
  inactiveDevices: stats.inactiveDevices,
  inactiveDeviceCount: stats.inactiveDevices.length
};

// Return the results
return [{ json: result }];
